const content={verivox:`<div class="eyebrow">CURRENT EXPERIENCE · MARCH 2026–PRESENT</div><h2>Verivox</h2><p>Software QA Engineer · Germany</p><p>I hold complete QA responsibility for the Verivox mobile app across iOS and Android, as its sole QA engineer.</p><ul><li><strong>Scope:</strong> End-to-end mobile QA ownership across both platforms.</li><li><strong>Automation tools:</strong> Detox and Appium.</li><li><strong>Perspective:</strong> Bringing experience in complex connected systems to consumer mobile quality.</li></ul>`,home:`<div class="eyebrow">PREVIOUS EXPERIENCE · MOBILE + IoT</div><h2>Connected-home quality</h2><p>At Resideo / Honeywell Home, my work spanned mobile automation frameworks, backend validation, CI/CD and device interoperability.</p><ul><li><strong>First Alert:</strong> Flutter mobile automation with Appium Flutter Driver for connected safety products.</li><li><strong>Resideo Pro:</strong> Automation for installer setup, configuration and diagnostics workflows.</li><li><strong>Resideo Home / Honeywell Home:</strong> Native iOS and Android automation for connected-home monitoring and control.</li><li><strong>Total Connect International EMEA:</strong> Mobile quality for regional heating and security products.</li></ul><p>Reported outcomes from this work include reducing major-release regression cycles from 25 to 10 days and increasing automation coverage from 30% to 60%.</p>`};const dialog=document.querySelector('dialog');document.querySelectorAll('[data-project]').forEach(b=>b.addEventListener('click',()=>{document.querySelector('#dialog-content').innerHTML=content[b.dataset.project];dialog.showModal()}));document.querySelector('.close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
